 const orders = new InMemoryOrderStore([{id:'probe-x', customerId:'owner-x', status:status as any, items:['a','b']}, {id:'untouched',customerId:'other-x',status:'pending',items:['c']}]);
 let writes=0; const save=orders.save.bind(orders); orders.save=o=>{writes++;save(o)};
