 const request=(id='probe-x',authorization:string|undefined='Bearer valid-x')=>router.handle({method:'POST',path:`/orders/${id}/cancel`,headers:{authorization},body:{customerId:'owner-x'}});
 return {orders,request,writes:()=>writes};
}
const a=setup(); const original=a.orders.all(); assert.equal(a.request().status,200); assert.deepEqual(a.orders.all(),original.map(o=>o.id==='probe-x'?{...o,status:'cancelled'}:o)); assert.equal(a.writes(),1); console.log('R1: 200, exactly one write, all fields and unrelated order preserved');
